const crypto = require('crypto');

// Get the signature from headers
const signature = $input.first().headers['x-workflow-signature'];
const workflowRunId = $input.first().headers['x-workflow-run-id'];
const secret = $vars.N8N_WEBHOOK_SECRET || 'default-secret';

// Get the raw body
const body = JSON.stringify($input.first().json);

// Verify signature
const expectedSignature = crypto
  .createHmac('sha256', secret)
  .update(body)
  .digest('hex');

const isValid = crypto.timingSafeEqual(
  Buffer.from(signature, 'hex'),
  Buffer.from(expectedSignature, 'hex')
);

if (!isValid) {
  throw new Error('Invalid webhook signature');
}

return {
  workflowRunId,
  action: $input.first().json.action,
  data: $input.first().json.data,
  timestamp: new Date().toISOString(),
  verified: true
};

const { workflowRunId, action, data } = $input.first().json;

// Process notification based on action
let notification = {
  workflowRunId,
  action,
  timestamp: new Date().toISOString(),
  processed: true
};

switch (action) {
  case 'workflow_completed':
    notification = {
      ...notification,
      type: 'success',
      message: `Workflow ${workflowRunId} completed successfully`,
      details: {
        service: data.service,
        status: data.status,
        result: data.result
      }
    };
    break;

  case 'workflow_failed':
    notification = {
      ...notification,
      type: 'error',
      message: `Workflow ${workflowRunId} failed`,
      details: {
        service: data.service,
        error: data.error
      }
    };
    break;

  default:
    notification = {
      ...notification,
      type: 'info',
      message: `Workflow ${workflowRunId}: ${action}`,
      details: data
    };
}

return notification;

const { workflowRunId, action, data } = $input.first().json;

// Process analytics data
const analytics = {
  workflowRunId,
  action,
  timestamp: new Date().toISOString(),
  metrics: {
    processingTime: data.processingTime,
    tokensUsed: data.tokensUsed,
    confidence: data.confidence,
    service: data.service
  },
  insights: []
};

// Generate insights based on metrics
if (data.processingTime) {
  const timeMs = parseFloat(data.processingTime.replace('s', '')) * 1000;
  if (timeMs > 5000) {
    analytics.insights.push('High processing time detected - consider optimization');
  }
}

if (data.tokensUsed && data.tokensUsed > 2000) {
  analytics.insights.push('High token usage - monitor costs');
}

if (data.confidence && data.confidence < 0.8) {
  analytics.insights.push('Low confidence score - review results');
}

return analytics;

const { workflowRunId, action, data } = $input.first().json;

// Process CRM update
const crmUpdate = {
  workflowRunId,
  action,
  timestamp: new Date().toISOString(),
  lead: {
    id: workflowRunId,
    service: data.service,
    value: data.value,
    status: data.status,
    lastActivity: new Date().toISOString()
  },
  actions: []
};

// Determine CRM actions based on data
if (data.status === 'qualified') {
  crmUpdate.actions.push({
    type: 'update_lead_status',
    status: 'qualified',
    priority: 'high'
  });

  if (data.value && data.value > 10000) {
    crmUpdate.actions.push({
      type: 'assign_to_sales',
      team: 'enterprise'
    });
  }
}

return crmUpdate;

// Store analytics data (in a real implementation, this would save to a database)
const analytics = $input.first().json;

// Log analytics for now
console.log('Analytics stored:', {
  workflowRunId: analytics.workflowRunId,
  metrics: analytics.metrics,
  insights: analytics.insights,
  timestamp: analytics.timestamp
});

return {
  stored: true,
  analyticsId: `analytics_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  ...analytics
};

// Update CRM system (in a real implementation, this would integrate with Salesforce, HubSpot, etc.)
const crmUpdate = $input.first().json;

// Log CRM update for now
console.log('CRM updated:', {
  workflowRunId: crmUpdate.workflowRunId,
  lead: crmUpdate.lead,
  actions: crmUpdate.actions,
  timestamp: crmUpdate.timestamp
});

return {
  updated: true,
  crmId: `crm_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  ...crmUpdate
};

// Assemble final response
const input = $input.first().json;

return {
  success: true,
  processed: true,
  timestamp: new Date().toISOString(),
  result: input
};
